    #region Helper Methods
    private string GetSelectedMaLopBo()
    {
        if (string.IsNullOrEmpty(SelectedLop)) return string.Empty;
        var lop = thData?.danhSachLopList?.FirstOrDefault(l => l.IdLopBo.ToString() == SelectedLop);
        return lop?.MaLopBo ?? string.Empty;
    }

    private string GetTenKhoiLop()
    {
        if (!string.IsNullOrEmpty(MaKhoiLopChuNhiem))
        {
            var khoi = thData.danhSachKhoiList.FirstOrDefault(k => k.MaKhoiBo.ToString() == MaKhoiLopChuNhiem);
            return khoi?.TenKhoi ?? "Khối chủ nhiệm";
        }
        return "Khối chủ nhiệm";
    }

    #region Teacher Methods
    private async Task CheckGiaoVienChuNhiem()
    {
        if (userRole == "GiaoVien" && giaovien != null)
        {
            if (giaovien.ma_lop != null && giaovien.ma_lop > 0)
            {
                IsGiaoVienChuNhiem = true;

                var lopChuNhiem = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo == giaovien.ma_lop);
                if (lopChuNhiem != null)
                {
                    tenLopChuNhiem = lopChuNhiem.TenLop;
                    LopChuNhiemId = lopChuNhiem.IdLopBo;
                    MaKhoiLopChuNhiem = lopChuNhiem.MaKhoiBo.ToString();

                    // Tự động chọn lớp/khối chủ nhiệm
                    SelectedLop = LopChuNhiemId.ToString();
                    SelectedKhoi = MaKhoiLopChuNhiem;
                }
                else
                {
                    IsGiaoVienChuNhiem = false;
                    tenLopChuNhiem = "Lớp không tồn tại";
                }
            }
            else
            {
                IsGiaoVienChuNhiem = false;
                tenLopChuNhiem = "Chưa có lớp";
            }
        }
    }

    private List<KeyValuePair<object, string>> GetTeacherKhoiOptions()
    {
        if (userRole != "GiaoVien" || !phanCongGiangDayList.Any())
            return KhoiLopOptions;

        if (IsGiaoVienChuNhiem && !string.IsNullOrEmpty(MaKhoiLopChuNhiem))
        {
            var khoi = thData.danhSachKhoiList.FirstOrDefault(k => k.MaKhoiBo.ToString() == MaKhoiLopChuNhiem);
            if (khoi != null)
            {
                return new List<KeyValuePair<object, string>>
                {
                    new KeyValuePair<object, string>(khoi.MaKhoiBo, khoi.TenKhoi)
                };
            }
        }

        var teacherLopHocIds = phanCongGiangDayList
            .Where(p => p.MaGiaoVien == maUser)
            .Select(p => p.IdLopBo)
            .Distinct()
            .ToList();

        var teacherKhoiIds = thData.danhSachLopList
            .Where(l => teacherLopHocIds.Contains(l.IdLopBo))
            .Select(l => l.MaKhoiBo)
            .Distinct()
            .ToList();

        return KhoiLopOptions.Where(k => teacherKhoiIds.Contains(k.Key)).ToList();
    }

    private List<KeyValuePair<object, string>> GetTeacherLopHocOptions()
    {
        if (userRole != "GiaoVien" || !phanCongGiangDayList.Any())
            return LopHocOptions;

        if (IsGiaoVienChuNhiem && LopChuNhiemId > 0)
        {
            var lopChuNhiem = thData.danhSachLopList.FirstOrDefault(l => l.IdLopBo == LopChuNhiemId);
            if (lopChuNhiem != null)
            {
                return new List<KeyValuePair<object, string>>
                {
                    new KeyValuePair<object, string>(lopChuNhiem.IdLopBo, lopChuNhiem.TenLop)
                };
            }
        }

        var teacherLopHocIds = phanCongGiangDayList
            .Where(p => p.MaGiaoVien == maUser)
            .Select(p => p.IdLopBo)
            .Distinct()
            .ToList();

        if (!string.IsNullOrEmpty(SelectedKhoi) && !string.IsNullOrWhiteSpace(SelectedKhoi))
        {
            teacherLopHocIds = thData.danhSachLopList
                .Where(l => teacherLopHocIds.Contains(l.IdLopBo) && l.MaKhoiBo.ToString() == SelectedKhoi)
                .Select(l => l.IdLopBo)
                .Distinct()
                .ToList();
        }

        return LopHocOptions.Where(l => teacherLopHocIds.Contains((int)l.Key)).ToList();
    }
    #endregion
    #endregion

    #region Filter Logic
    private void GetDataOfKhoi()
    {
        KhoiLopOptions.Clear();
        foreach (var khoilop in thData.danhSachKhoiList)
        {
            KhoiLopOptions.Add(new KeyValuePair<object, string>(khoilop.MaKhoiBo, khoilop.TenKhoi));
        }
        UpdateKhoiLopOptions();
    }

    private void GetDataOfLop()
    {
        LopHocOptions.Clear();
        foreach (var lophoc in thData.danhSachLopList)
        {
            LopHocOptions.Add(new KeyValuePair<object, string>(lophoc.IdLopBo, lophoc.TenLop));
        }
    }

    private void UpdateKhoiLopOptions()
    {
        if (userRole != "GiaoVien")
        {
            FilteredKhoiLopOptions = KhoiLopOptions;
        }
        else
        {
            FilteredKhoiLopOptions = GetTeacherKhoiOptions();
        }
    }

    private void OnKhoiLopChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;

        SelectedKhoi = e.Value?.ToString() ?? string.Empty;
        SelectedLop = string.Empty;

        UpdateLopHocOptions();

        if (FilteredLopHocOptions.Any())
        {
            SelectedLop = FilteredLopHocOptions.First().Key.ToString() ?? string.Empty;
        }

        StateHasChanged();
    }

    private void UpdateLopHocOptions()
    {
        if (userRole != "GiaoVien")
        {
            FilteredLopHocOptions = LopHocOptions
                .Where(lop =>
                    string.IsNullOrEmpty(SelectedKhoi) ||
                    thData.danhSachLopList.Any(l => l.IdLopBo.ToString() == lop.Key.ToString() && l.MaKhoiBo.ToString() == SelectedKhoi))
                .ToList();
        }
        else
        {
            FilteredLopHocOptions = GetTeacherLopHocOptions();
        }
    }

    private void OnLopHocChange(ChangeEventArgs e)
    {
        if (IsGiaoVienChuNhiem) return;

        SelectedLop = e.Value?.ToString() ?? string.Empty;
        StateHasChanged();
    }

    private void SwitchView(string view)
    {
        CurrentView = view;
    }
    #endregion

    #region Load Data
    private async Task LoadData()
    {
        try
        {
            isLoading = true;
            StateHasChanged();

            if (userRole == "GiaoVien" && string.IsNullOrEmpty(SelectedLop))
            {
                await JS.InvokeVoidAsync("alert", "Giáo viên cần chọn lớp để đánh giá");
                return;
            }

            if (IsGiaoVienChuNhiem && (string.IsNullOrEmpty(SelectedLop) || SelectedLop != LopChuNhiemId.ToString()))
            {
                SelectedLop = LopChuNhiemId.ToString();
            }

            await Task.Delay(100);
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadLevelFromStorage()
    {
        try
        {
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel");

            if (string.IsNullOrEmpty(selectedCapHoc))
            {
                selectedCapHoc = "02";
                await BrowserStorageService.SetItem(JS, "selectedLevel", selectedCapHoc);
                await BrowserStorageService.SetItem(JS, "selectedLevelText", "Cấp Tiểu học");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Lỗi khi đọc cấp học từ Local Storage: {ex.Message}");
            selectedCapHoc = "02";
        }
    }

    private void SetDefaultKhoiAndLopIfNeeded()
    {
        if (IsGiaoVienChuNhiem)
            return;

        if (string.IsNullOrEmpty(SelectedKhoi) && FilteredKhoiLopOptions.Any())
        {
            SelectedKhoi = FilteredKhoiLopOptions.First().Key.ToString() ?? string.Empty;
        }

        UpdateLopHocOptions();

        if (string.IsNullOrEmpty(SelectedLop) && FilteredLopHocOptions.Any())
        {
            SelectedLop = FilteredLopHocOptions.First().Key.ToString() ?? string.Empty;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadLevelFromStorage();

        var authState = await AuthenticationStateProvider.GetAuthenticationStateAsync();
        var user = authState.User;

        if (user.Identity is not null && user.Identity.IsAuthenticated)
        {
            maUser = user.FindFirst("MaUser")?.Value ?? "Không tìm thấy";
            userRole = user.FindFirst(ClaimTypes.Role)?.Value ?? "Không có role";
        }

        SelectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2023-2024";
        SelectedHocKy = await BrowserStorageService.GetItem(JS, "selectedHocKy") ?? "1";

        maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);

        if (userRole == "GiaoVien")
        {
            giaovien = await TruongService.hGetGiaoVienByIdAsync(maUser, maTruongBo, SelectedNamHoc);
        }

        thData.danhSachKhoiList = await TruongService.hGetDanhSachKhoi(maTruongBo, selectedCapHoc);
        thData.danhSachLopList = await TruongService.hGetDanhSachLop(maTruongBo, selectedCapHoc, SelectedNamHoc);

        // Build lopDict từ danhSachLopList đã load để join tên lớp/khối ở application layer
        var lopDict = thData.danhSachLopList
            .ToDictionary(l => l.IdLopBo, l => (l.TenLop, l.MaKhoiBo));

        // Load toàn bộ phân công của trường (dùng để lọc giáo viên theo lớp)
        phanCongGiangDayList = await TruongService.hGetDanhSachPhanCongGiangDay(maTruongBo, SelectedNamHoc, lopDict: lopDict);

        GetDataOfKhoi();
        GetDataOfLop();

        // Kiểm tra GVCN — sẽ tự động set SelectedKhoi, SelectedLop nếu có lớp chủ nhiệm
        await CheckGiaoVienChuNhiem();

        // Tự động chọn khối/lớp đầu tiên nếu chưa được chọn (và không phải GVCN)
        SetDefaultKhoiAndLopIfNeeded();

        StateHasChanged();
    }
    #endregion

